import { Component, For, ParentComponent, Show, type JSX } from "solid-js";

import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { InnerFrame } from "#core/ui-next/components/inner-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { PanelProps } from "#core/ui-next/components/panel.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { TicketBox } from "#core/ui-next/screens/create-game/ticket-box.jsx";

import { GovtScreenModel } from "#base/ui/policies/model-government.js";
import { PoliciesModel } from "#base/ui/policies/model-policies.js";

export const GovernmentOverview: ParentComponent<PanelProps> = () => {
	let root: HTMLDivElement | undefined;

	const govModel = GovtScreenModel.get();
	const policyModel = PoliciesModel.get();

	return (
		<NestedTooltipContext.Provider value={{ disabled: true }}>
			<div
				class="flex-auto flex text-center flex-col px-2 pb-4"
				ref={root}
			>
				<div class="p-3 flex-auto flex flex-row w-full">
					<div class="gov-outer-container py-3 px-6 flex-1 h-full mx-2">
						<div class="flex flex-row mr-1 w-full" />
						<ScrollArea
							class={"flex-auto h-full"}
							useProxy={true}
						>
							<div class="flex w-full flex-col ">
								<FiligreeTitle.H4
									text="LOC_UI_POLICIES_CURRENT_GOVERNMENT"
									filigree-style="h4"
									class="mt-4 mb-3"
								/>
								<InnerFrame class="flex flex-col items-center relative px-2">
									<Show
										when={govModel.data.hasGovtBeenChosen}
										fallback={
											<L10n.Stylize
												class={"py-9 text-accent-4"}
												text="LOC_UI_NO_GOVERNMENT_CHOSEN"
												role="heading"
											/>
										}
									>
										<div class="relative font-body-base text-accent-2 p-6 my-px flex flex-col items-center">
											<L10n.Stylize
												text={govModel.data.governmentName}
												class={"uppercase relative font-bold tracking-150 font-title-2xl"}
												role="heading"
											/>
											<div class="policies__overview-government-divider w-128 h-px mt-3 mb-2" />

											<L10n.Stylize
												text={"LOC_UI_GOVERNMENT_ABILITY"}
												class={
													"uppercase relative text-accent-4 font-title-sm tracking-100 mt-5 mb-2"
												}
												role="heading"
											/>

											<L10n.Stylize
												text={govModel.data.governmentAbilityDescription}
												class={"relative text-accent-3 mb-4"}
												role="article"
											/>
										</div>
									</Show>
								</InnerFrame>
							</div>
							<div class="flex w-full flex-col ">
								<FiligreeTitle.H4
									text="LOC_UI_CELEBRATION_OPTIONS"
									filigree-style="h4"
									class="mt-4 mb-3"
								/>
								<InnerFrame class="flex flex-col items-center relative px-2">
									<Show
										when={govModel.data.hasGovtBeenChosen}
										fallback={
											<L10n.Stylize
												class={"py-9 text-accent-4"}
												text="LOC_UI_NO_GOVERNMENT_CHOSEN"
												role="heading"
											/>
										}
									>
										<Show when={govModel.data.celebrationBonusItems.length < 3}>
											<div class="relative flex flex-col items-center">
												<L10n.Stylize
													text={govModel.data.governmentDescription}
													class={"relative text-accent-4 font-sm mt-4"}
												/>
											</div>
											<div class="policies__overview-government-divider w-128 h-px mt-3" />
										</Show>
										<div class="relative font-body-base px-8 py-4 my-px flex flex-col items-center">
											<div class="relative flex flex-col items-start">
												<For each={govModel.data.celebrationBonusItems}>
													{(item) => (
														<CelebrationItem
															description={item.description ?? ""}
															image={item.image ?? ""}
															overFourItems={
																govModel.data.celebrationBonusItems.length > 3
															}
														/>
													)}
												</For>
											</div>
										</div>
									</Show>
								</InnerFrame>
								<Show when={govModel.data.hasGovtBeenChosen && govModel.data.govtTraditions.length > 0}>
									<FiligreeTitle.H4
										text="LOC_UI_TRADITIONS_TITLE"
										filigree-style="h4"
										class="mt-4 mb-3"
									/>
									<InnerFrame class="flex flex-col items-center relative px-2">
										<Show
											when={govModel.data.hasGovtBeenChosen}
											fallback={
												<L10n.Stylize
													class={"py-9 text-accent-4"}
													text="LOC_UI_NO_GOVERNMENT_CHOSEN"
													role="heading"
												/>
											}
										>
											<div class="relative font-body-base px-8 py-3 my-px flex flex-col w-full items-center">
												<div class="relative flex flex-col items-start w-full">
													<For each={govModel.data.govtTraditions}>
														{(item) => (
															<div class="flex flex-auto flex-col w-full">
																<TraditionItem
																	itemName={item.def.Name}
																	description={item.def.Description ?? ""}
																	addtionalDescription={item.unlock}
																	image={`url(blp:unlock_tradition)`}
																/>
																<Show
																	when={
																		item !=
																		govModel.data.govtTraditions[
																			govModel.data.govtTraditions.length - 1
																		]
																	}
																>
																	<Divider />
																</Show>
															</div>
														)}
													</For>
												</div>
											</div>
										</Show>
									</InnerFrame>
								</Show>
							</div>
						</ScrollArea>
					</div>
					{/* Right side of screen */}
					<div class="gov-outer-container p-3 h-full flex-1 mx-2 w-full">
						<ScrollArea
							class={"flex-auto h-full"}
							useProxy={true}
						>
							<FiligreeTitle.H4
								text="LOC_TAG_CONSTRUCTIBLE_HAPPINESS"
								filigree-style="h4"
								class="mt-4 mb-3"
							/>
							<InnerFrame class="p-2 flex flex-auto w-full">
								<div class="p-5 w-full">
									<div
										role="heading"
										class="text-accent-2 font-title uppercase tracking-100 bg-primary-4 w-full p-3"
									>
										<L10n.Stylize text="LOC_UI_SETTLEMENT_HAPPINESS" />
									</div>
									<div class="w-full mx-8 mb-12 bg-primary-5 ">
										<For each={govModel.data.settlementHappiness()}>
											{(item, index) => (
												<HappinessRow
													index={index()}
													happinessRange={item.happinessRange}
													iconName={item.icon}
													rowName={item.stageName}
													amount={item.settlements}
													class={item.textColor}
												/>
											)}
										</For>
									</div>
								</div>
								<TicketBox class="flex items-center relative">
									<div
										class={`flex items-center relative w-full justify-between ${policyModel.isSmallScreen() ? "pr-8 pl-5" : "pr-18 pl-10"}  `}
									>
										<div class="flex flex-auto items-center mr-5">
											<RingMeter
												value={govModel.data.happinessRing}
												min={0}
												max={100}
												ringImage={"url(blp:govt_happ_circle_rad)"}
												class="policies__overview-happiness-meter size-28 flex items-center justify-center"
											>
												<div class="policies__overview-happiness-meter-circle bg-no-repeat bg-center bg-cover size-22 flex items-center justify-center">
													<div class="policies__overview-happiness-meter-image bg-no-repeat bg-center bg-cover size-12" />
												</div>
											</RingMeter>
											<div class="flex flex-col flex-auto pointer-events-auto">
												<div
													class="policies__overview-turns-left-number font-body-sm"
													role="heading"
												/>
												<L10n.Stylize
													class="font-body-sm"
													text={govModel.data.celebrationTurnsLeft}
												/>
											</div>
										</div>
										<div
											class="flex flex-auto justify-end"
											role="article"
										>
											<div
												class="flex flex-col text-accent-2 items-center pointer-events-auto"
												role="article"
											>
												<div
													data-l10n-id="LOC_ATTR_YIELD_INCOME"
													class="font-title-xs uppercase text-accent-3 tracking-100"
												/>
												<div class="font-body tracking-100 max-w-60 mb-3">
													<L10n.Stylize text={govModel.data.happinessPerTurn} />
												</div>
												<L10n.Stylize
													class="text-accent-3 font-title-xs tracking-100 uppercase"
													text={"LOC_UI_HAPPINESS_NEEDED"}
												/>
												{govModel.data.happinessNeeded +
													"/" +
													govModel.data.happinessNextCelebrationThreshold}
											</div>
										</div>
									</div>
								</TicketBox>
								<L10n.Stylize
									class={"p-6 text-accent-4"}
									text={"LOC_GOVERNMENT_HAPPINESS_REMINDER_TEXT"}
									role={"article"}
								/>
							</InnerFrame>
						</ScrollArea>
					</div>
				</div>
			</div>
		</NestedTooltipContext.Provider>
	);
};

interface GovtDisplayItem extends JSX.HTMLAttributes<HTMLDivElement> {
	itemName?: string;
	image: string;
	description: string;
	addtionalDescription?: string;
	overFourItems?: boolean;
}

const CelebrationItem: Component<GovtDisplayItem> = (props) => {
	return (
		<div class="w-full text-accent-3 flex items-center flex-row mb-4">
			<Icon
				class={`${props.overFourItems ? "size-6" : "size-10"}`}
				name={props.image}
				isUrl={true}
			/>

			<L10n.Stylize
				class={`ml-1 flex flex-auto text-left ${props.overFourItems ? "text-xs" : ""}`}
				text={props.description}
			/>
		</div>
	);
};

const TraditionItem: Component<GovtDisplayItem> = (props) => {
	return (
		<div class="w-full text-accent-3 flex items-center flex-row mb-2">
			<Icon
				class="size-10"
				name={props.image}
				isUrl={true}
			/>
			<Divider vertical={true} />
			<div
				class="flex flex-col ml-1 flex-auto text-left"
				role="article"
			>
				<L10n.Stylize
					class="text-secondary uppercase tracking-100 font-title-sm"
					text={props.itemName ?? ""}
				/>
				<L10n.Stylize
					class="text-sm"
					text={props.addtionalDescription ?? ""}
				/>
				<L10n.Stylize
					class="text-sm text-accent-2"
					text={props.description}
				/>
			</div>
		</div>
	);
};

interface DividerProps {
	vertical?: true;
}

const Divider: Component<DividerProps> = (props) => {
	return <div class={`${props.vertical ? "h-full w-px mx-2" : "w-full h-px my-2"} flex bg-primary-3`} />;
};

interface HappinessTableProps extends JSX.HTMLAttributes<HTMLDivElement> {
	rowName?: string;
	amount?: number;
	iconName?: string;
	index: number;
	happinessRange: string;
}

const HappinessRow: Component<HappinessTableProps> = (props) => {
	return (
		<div
			class={`py-2 pl-2 pr-12 items-center flex flex-auto ${props.class} ${props.index % 2 === 0 ? "overview-happiness-row-1" : ".overview-happiness-row-2"} border-primary-3 border w-full justify-between`}
			role="article"
		>
			<Icon
				class={"size-8"}
				name={props.iconName}
			/>
			<div class="flex flex-row w-full justify-between">
				<div class="flex flex-row items-center">
					<L10n.Stylize
						class={"uppercase"}
						text={props.rowName ?? ""}
					/>
					<L10n.Stylize
						class="ml-4 text-accent-4 text-xs"
						text={props.happinessRange}
					/>
				</div>
				<span class="font-bold">{props.amount}</span>
			</div>
		</div>
	);
};
